from pathlib import Path
import json,html
# Shared geometry for SVG and vector PDF diagrams.
figures={
'deployment':{'size':[1000,560],'title':'Current deployment: the agent runs in the cloud','groups':[(245,15,735,175,'CLOUDFLARE','cloud'),(15,235,600,300,'AWS EC2 - ONE LINUX VM','aws')],'nodes':[(15,55,195,95,'Your device',['Browser only','No local agent process'],'plain'),(270,60,260,95,'Worker + web app',['HTTPS, login, API routing'],'cloud'),(610,60,340,95,'Durable Object + SQLite',['Task state, permissions, artifacts'],'cloud'),(40,290,250,85,'Cloud Codex gateway',['Native app-server','Jarvis agent session'],'aws'),(335,290,250,85,'Executor supervisor',['Authenticated tool dispatch'],'aws'),(40,440,250,65,'Python sandbox',['No network; resource limits'],'plain'),(335,440,250,65,'Chromium sandbox',['Playwright; public-only proxy'],'plain'),(690,290,280,100,'External model APIs',['OpenRouter routes inference','Jarvis + optional Friday'],'model'),(690,440,280,65,'Other external services',['Search, Gmail, Telegram, MCP'],'plain')],'edges':[[(210,102),(270,102)],[(530,102),(610,102)],[(735,155),(735,210),(165,210),(165,290)],[(790,155),(790,225),(460,225),(460,290)],[(290,333),(312,333),(312,410),(655,410),(655,340),(690,340)],[(400,375),(400,410),(165,410),(165,440)],[(510,375),(510,440)],[(950,155),(985,155),(985,472),(970,472)]]},
'task-flow':{'size':[1000,440],'title':'One mission: persistent state around each tool','groups':[],'nodes':[(20,50,280,90,'1. Submit mission',['Browser sends request','Worker authenticates owner'],'cloud'),(360,50,280,90,'2. Persist and plan',['Durable Object saves task','Codex chooses next tool'],'cloud'),(700,50,280,90,'3. Check permission',['Validate exact arguments','Approve protected effects'],'plain'),(700,270,280,100,'4. Execute real tool',['Search, Chromium or Python','Persist result and receipt'],'aws'),(360,270,280,100,'5. Observe and continue',['Return evidence to Codex','Adapt or finish the task'],'aws'),(20,270,280,100,'6. Deliver artifact',['Store named HTML / PDF','Show Result and download'],'cloud')],'edges':[[(300,95),(360,95)],[(640,95),(700,95)],[(840,140),(840,270)],[(700,320),(640,320)],[(360,320),(300,320)],[(500,270),(500,210),(840,210),(840,140)]]},
'privacy':{'size':[1000,355],'title':'Optional local evidence: owner controls disclosure','groups':[(15,30,610,285,'OPTIONAL LAPTOP COMPANION','plain'),(660,30,325,285,'CLOUD','cloud')],'nodes':[(35,90,250,85,'Selected private folder',['Local files + SQLite index'],'plain'),(330,90,270,85,'Review exact excerpt',['Owner chooses release','Bound to task + recipient'],'plain'),(690,90,265,85,'Approved excerpt only',['Cloud task / model provider','API inference is disclosure'],'cloud'),(175,220,310,65,'No approval: no release',['Unselected files stay local'],'plain')],'edges':[[(285,132),(330,132)],[(600,132),(690,132)],[(465,175),(465,205),(330,205),(330,220)]]},
'elastic':{'size':[1000,475],'title':'PROPOSED: demand-driven AWS start and safe idle stop','groups':[],'nodes':[(20,50,280,95,'1. Durable pending task',['Office stays online','Authenticated wake request'],'cloud'),(360,50,280,95,'2. Short wake controller',['API Gateway + Lambda','Start allowed EC2 instance'],'model'),(700,50,280,95,'3. VM boots; reports ready',['Named tunnel + services','Dispatch only when healthy'],'aws'),(700,295,280,100,'4. Task holds active lease',['Heartbeat while tools run','Checkpoint and save receipts'],'aws'),(360,295,280,100,'5. Verify true idle',['EventBridge / idle controller','Drain; reject uncertain state'],'model'),(20,295,280,100,'6. Stop EC2 safely',['Compute off; EBS remains','Next task requests wake'],'plain')],'edges':[[(300,97),(360,97)],[(640,97),(700,97)],[(840,145),(840,295)],[(700,345),(640,345)],[(360,345),(300,345)],[(160,295),(160,145)]]}}
colors={'plain':('#f7f8f6','#a7b6b4'),'cloud':('#eaf6f4','#4c8c85'),'aws':('#fff3e2','#c58e40'),'model':('#f0eefb','#8770ad')}
folder=Path('public/diagrams');folder.mkdir(exist_ok=True)
for key,f in figures.items():
 w,h=f['size'];out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title"><title id="title">{html.escape(f["title"])}</title><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9" fill="#42636a"/></marker></defs><rect width="100%" height="100%" fill="white"/>']
 for x,y,bw,bh,label,t in f['groups']:
  fill,stroke=colors[t];out.append(f'<rect x="{x}" y="{y}" width="{bw}" height="{bh}" rx="14" fill="{fill}" stroke="{stroke}"/><text x="{x+18}" y="{y+26}" font-family="Arial,sans-serif" font-size="17" font-weight="bold" fill="#263f47">{html.escape(label)}</text>')
 for points in f['edges']:out.append('<polyline points="'+' '.join(f'{x},{y}' for x,y in points)+'" fill="none" stroke="#42636a" stroke-width="2" marker-end="url(#arrow)"/>')
 for x,y,bw,bh,title,body,t in f['nodes']:
  fill,stroke=colors[t];out.append(f'<rect x="{x}" y="{y}" width="{bw}" height="{bh}" rx="10" fill="white" stroke="{stroke}" stroke-width="1.5"/><text x="{x+14}" y="{y+27}" font-family="Arial,sans-serif" font-size="17" font-weight="bold" fill="#193a43">{html.escape(title)}</text>')
  for i,line in enumerate(body):out.append(f'<text x="{x+14}" y="{y+49+i*20}" font-family="Arial,sans-serif" font-size="16" fill="#435a62">{html.escape(line)}</text>')
 out.append('</svg>');(folder/(key+'.svg')).write_text(''.join(out),encoding='utf-8')
Path('work').mkdir(exist_ok=True)
Path('work/guide-diagrams.json').write_text(json.dumps(figures),encoding='utf-8')
print('Four vector diagrams created')
